package id.bangsadigital.riosense.voice

import android.content.res.AssetManager
import java.io.BufferedInputStream
import java.io.DataInputStream
import java.nio.ByteBuffer
import java.nio.ByteOrder
import kotlin.math.min

/**
 * Pure-Kotlin SentencePiece Unigram Viterbi tokenizer for XLM-RoBERTa /
 * paraphrase-multilingual-MiniLM-L12-v2.
 *
 * Loads the compact binary vocabulary (`assets/nlu/spm_vocab.bin`) generated by
 * `scripts/prepare_nlu_assets.mjs` in ~25 ms with zero native C++ dependencies.
 */
class UnigramTokenizer private constructor(
    private val tokenToId: HashMap<String, Int>,
    private val scores: FloatArray,
    private val maxTokenLen: Int
) {
    fun encode(rawText: String, maxSeqLen: Int = MAX_SEQ_LEN): LongArray {
        val normalized = rawText.trim().replace(WHITESPACE_REGEX, " ")
        if (normalized.isEmpty()) {
            return longArrayOf(BOS_ID.toLong(), EOS_ID.toLong())
        }

        val out = ArrayList<Long>(min(maxSeqLen, 32))
        out.add(BOS_ID.toLong())

        val words = normalized.split(' ')
        for (word in words) {
            if (word.isEmpty()) continue
            val pieceWord = "$METASPACE$word"
            val subIds = viterbiEncode(pieceWord)
            for (id in subIds) {
                out.add(id.toLong())
                if (out.size >= maxSeqLen - 1) break
            }
            if (out.size >= maxSeqLen - 1) break
        }

        out.add(EOS_ID.toLong())
        return out.toLongArray()
    }

    private fun viterbiEncode(text: String): IntArray {
        val n = text.length
        val bestScore = DoubleArray(n + 1) { -1e18 }
        val bestPrev = IntArray(n + 1) { -1 }
        val bestId = IntArray(n + 1) { UNK_ID }
        bestScore[0] = 0.0

        for (i in 0 until n) {
            if (bestScore[i] <= -1e17) continue
            val maxEnd = min(n, i + maxTokenLen)
            var matchedAny = false

            for (end in (i + 1)..maxEnd) {
                val sub = text.substring(i, end)
                val id = tokenToId[sub]
                if (id != null) {
                    matchedAny = true
                    val candidate = bestScore[i] + scores[id]
                    if (candidate > bestScore[end]) {
                        bestScore[end] = candidate
                        bestPrev[end] = i
                        bestId[end] = id
                    }
                }
            }

            if (!matchedAny) {
                val candidate = bestScore[i] - 20.0
                if (candidate > bestScore[i + 1]) {
                    bestScore[i + 1] = candidate
                    bestPrev[i + 1] = i
                    bestId[i + 1] = UNK_ID
                }
            }
        }

        val reversed = ArrayList<Int>(n)
        var cursor = n
        while (cursor > 0 && bestPrev[cursor] >= 0) {
            reversed.add(bestId[cursor])
            cursor = bestPrev[cursor]
        }

        val result = IntArray(reversed.size)
        for (idx in reversed.indices) {
            result[idx] = reversed[reversed.size - 1 - idx]
        }
        return result
    }

    companion object {
        private const val BOS_ID = 0
        private const val EOS_ID = 2
        private const val UNK_ID = 3
        private const val METASPACE = '\u2581'
        private const val MAX_SEQ_LEN = 48
        private val WHITESPACE_REGEX = Regex("\\s+")

        fun loadFromAssets(assets: AssetManager, assetPath: String): UnigramTokenizer {
            val bytes = assets.open(assetPath).use { input ->
                BufferedInputStream(input, 65536).readBytes()
            }
            val buf = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN)
            val vocabSize = buf.int

            val tokenToId = HashMap<String, Int>((vocabSize * 1.34f).toInt())
            val scores = FloatArray(vocabSize)
            var maxLen = 1

            for (id in 0 until vocabSize) {
                val utf8Len = buf.short.toInt() and 0xFFFF
                val strBytes = ByteArray(utf8Len)
                buf.get(strBytes)
                val piece = String(strBytes, Charsets.UTF_8)
                val score = buf.float
                scores[id] = score
                if (id >= 4 && piece.isNotEmpty()) {
                    tokenToId[piece] = id
                    if (piece.length > maxLen) {
                        maxLen = piece.length
                    }
                }
            }

            return UnigramTokenizer(
                tokenToId = tokenToId,
                scores = scores,
                maxTokenLen = maxLen
            )
        }
    }
}
